import type { Lang } from "./canon";

export interface Translation {
  id: string;
  abbr: string;
  name: string;
  nativeName: string;
  language: Lang;
  license: string;
  attribution: string;
  source: string;
  books: string[];
}

/**
 * Bundled translations (mirrors public/bibles/index.json, generated by
 * scripts/bibles/build.mjs). Kept static so the UI works before any fetch.
 */
export const TRANSLATIONS: (Pick<Translation, "id" | "abbr" | "name" | "nativeName" | "language" | "license"> & { attribution?: string })[] = [
  { id: "te-irv", abbr: "IRV", name: "Indian Revised Version (Telugu)", nativeName: "ఇండియన్ రివైజ్డ్ వెర్షన్", language: "te", license: "CC BY-SA 4.0", attribution: "Original work available at http://www.freebiblesindia.in" },
  { id: "te-ov", abbr: "OV", name: "Telugu Old Version (BSI)", nativeName: "పరిశుద్ధ గ్రంథము (పాత అనువాదము)", language: "te", license: "See docs/BIBLES.md" },
  { id: "en-kjv", abbr: "KJV", name: "King James Version", nativeName: "King James Version", language: "en", license: "Public Domain" },
  { id: "en-bsb", abbr: "BSB", name: "Berean Standard Bible", nativeName: "Berean Standard Bible", language: "en", license: "Public Domain" },
  { id: "en-web", abbr: "WEB", name: "World English Bible", nativeName: "World English Bible", language: "en", license: "Public Domain" },
  { id: "en-asv", abbr: "ASV", name: "American Standard Version (1901)", nativeName: "American Standard Version", language: "en", license: "Public Domain" },
  { id: "en-bbe", abbr: "BBE", name: "Bible in Basic English", nativeName: "Bible in Basic English", language: "en", license: "Public Domain" },
  { id: "en-darby", abbr: "DARBY", name: "Darby Translation", nativeName: "Darby Translation", language: "en", license: "Public Domain" },
];

export const TRANSLATION_BY_ID = Object.fromEntries(TRANSLATIONS.map((t) => [t.id, t]));

export function translationLang(id: string): Lang {
  return (TRANSLATION_BY_ID[id]?.language ?? "en") as Lang;
}
